import pandas as pd
import matplotlib.pyplot as plt

# Load telemetry generated by the C++ engine
df = pd.read_csv("telemetry.csv")

plt.style.use("seaborn-v0_8-darkgrid" if "seaborn-v0_8-darkgrid" in plt.style.available else "default")
fig, ax = plt.subplots(figsize=(10, 6), dpi=150)

# Plot actual state error and filter 1-sigma uncertainty
ax.plot(df["step"], df["pos_error_km"], label="True Position Error (km)", color="#e63946", lw=2)
ax.plot(df["step"], df["sigma_km"], label="EKF 1-Sigma Bound (km)", color="#1d3557", lw=2, linestyle="--")

ax.set_yscale("log")
ax.set_title("XNAV Relativistic Position Error Convergence (SSB Frame)", fontsize=13, fontweight="bold", pad=12)
ax.set_xlabel("Navigation Epoch (Step = 60s)", fontsize=11)
ax.set_ylabel("Error / Uncertainty (km, Log Scale)", fontsize=11)
ax.grid(True, which="both", linestyle=":", alpha=0.6)
ax.legend(frameon=True, facecolor="white", edgecolor="none")

plt.tight_layout()
output_image = "data/xnav_convergence.png"
plt.savefig(output_image, dpi=300)
print(f"[SUCCESS] Plot saved to '{output_image}'. Displaying now...")
plt.show()